#!/bin/sh
# Generated by forge. SessionEnd: unregisters this session from the types engines; the
# last session of the repository to end stops them (§15.3). Prints nothing.
# this script's directory, absolute (builtins)
case $0 in */*) dir=${0%/*} ;; *) dir=. ;; esac
case $dir in /*) ;; *) dir=$PWD/$dir ;; esac
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
repo_root || exit 0
forge_types_session end
exit 0
